import boto3

def create_observability_client():
    return boto3.client('cloudwatch')

class MetricRequest:
    def __init__(self, metric_name, start_time, end_time, dimensions=None):
        self.metric_name = metric_name
        self.start_time = start_time
        self.end_time = end_time
        self.dimensions = dimensions or []

class MetricResponse:
    def __init__(self, datapoints):
        self.datapoints = datapoints

    def normalize(self):
        return [dp for dp in self.datapoints if dp['Timestamp'] is not None]

import re

def check_unsafe_text(text):
    unsafe_patterns = [r'\b(badword1|badword2)\b', r'\b(unsafe1|unsafe2)\b']
    for pattern in unsafe_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return True
    return False

import boto3

def archive_metric_snapshots(bucket_name, prefix):
    s3 = boto3.client('s3')
    response = s3.list_objects_v2(Bucket=bucket_name, Prefix=prefix)
    if 'Contents' in response:
        for obj in response['Contents']:
            s3.copy_object(Bucket=bucket_name, CopySource={'Bucket': bucket_name, 'Key': obj['Key']}, Key=f"archive/{obj['Key']}")
            s3.delete_object(Bucket=bucket_name, Key=obj['Key'])
